mapper.select:
SELECT DISTINCT 'SLEEP' AS metric, source_name COLLATE utf8mb4_0900_bin AS source_name
FROM sleep_records WHERE user_id=#{userId} AND sleep_date BETWEEN #{start} AND #{end}
AND source_name=#{request.sleepSource}
UNION ALL
SELECT DISTINCT 'STEPS' AS metric, source_name COLLATE utf8mb4_0900_bin AS source_name
FROM step_records WHERE user_id=#{userId} AND activity_date BETWEEN #{start} AND #{end}
AND source_name=#{request.stepSource}
UNION ALL
SELECT DISTINCT 'WORKOUT' AS metric, source_name COLLATE utf8mb4_0900_bin AS source_name
FROM workout_records WHERE user_id=#{userId} AND end_time > #{start} AND start_time < DATE_ADD(#{end}, INTERVAL 1 DAY)
AND source_name=#{request.workoutSource}
UNION ALL
SELECT DISTINCT 'MEAL' AS metric, source_name COLLATE utf8mb4_0900_bin AS source_name
FROM meal_records WHERE user_id=#{userId} AND consumed_at >= #{start} AND consumed_at < DATE_ADD(#{end}, INTERVAL 1 DAY)
AND source_name=#{request.mealSource}
UNION ALL
SELECT DISTINCT 'WATER' AS metric, source_name COLLATE utf8mb4_0900_bin AS source_name
FROM water_records WHERE user_id=#{userId} AND consumed_at >= #{start} AND consumed_at < DATE_ADD(#{end}, INTERVAL 1 DAY)
AND source_name=#{request.waterSource}
UNION ALL
SELECT DISTINCT 'WEIGHT' AS metric, source_name COLLATE utf8mb4_0900_bin AS source_name
FROM weight_records WHERE user_id=#{userId} AND measured_at >= #{start} AND measured_at < DATE_ADD(#{end}, INTERVAL 1 DAY)
AND source_name=#{request.weightSource}
ORDER BY metric,source_name
